import { MakeLogicType, actions, connect, kea, listeners, path } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { urls } from 'scenes/urls'

import { stashPendingAiPrompt } from '~/layout/ai/pendingAiPrompt'
import { runnerPanelLogic } from '~/layout/ai/runnerPanelLogic'

export const TODAY_HOME_PANEL_ID = 'today-home'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeComposerLogicActions {
    handOffToClassic: (prompt: string) => {
        prompt: string
    } // runnerPanelLogic
    homeTaskStarted: (taskId: string) => {
        taskId: string
    }
}

export type todayHomeComposerLogicType = MakeLogicType<{}, todayHomeComposerLogicActions>

export const todayHomeComposerLogic = kea<todayHomeComposerLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayHomeComposerLogic']),
    connect(() => ({
        actions: [runnerPanelLogic({ panelId: TODAY_HOME_PANEL_ID }), ['handOffToClassic']],
    })),
    actions({
        homeTaskStarted: (taskId: string) => ({ taskId }),
    }),
    listeners({
        homeTaskStarted: ({ taskId }) => {
            posthog.capture('today home task started')
            router.actions.push(urls.aiTask(taskId))
        },
        handOffToClassic: ({ prompt }) => {
            stashPendingAiPrompt(prompt)
            router.actions.push(urls.ai())
        },
    }),
])
